import React from "react";

function Home({ authToken, userEmail, onNavigate, onLogout, darkMode, toggleDarkMode }) {
  const [showNavDropdown, setShowNavDropdown] = React.useState(false);
  const [showUserDropdown, setShowUserDropdown] = React.useState(false);
  const [userDropdownTimeout, setUserDropdownTimeout] = React.useState(null);

  const handleUserMouseEnter = () => {
    if (userDropdownTimeout) clearTimeout(userDropdownTimeout);
    setShowUserDropdown(true);
  };

  const handleUserMouseLeave = () => {
    const timeout = setTimeout(() => setShowUserDropdown(false), 200);
    setUserDropdownTimeout(timeout);
  };

  const handleSettings = () => {
    onNavigate("app-settings");
  };

  const handleHelp = () => {
    alert("📚 Pentru ajutor, contactează robertachiton@gmail.com");
  };

  return (
    <div className="animated-bg" style={{ minHeight: "100vh" }}>
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <div className="logo" onClick={() => onNavigate("main")} style={{ cursor: "pointer" }}>
            🍳 SmartChef
          </div>
          <div className="nav-buttons">
            {authToken ? (
              <>
                {/* Right side - Menu & User */}
                <div style={{ display: "flex", gap: "0.8rem", alignItems: "center", marginLeft: "auto", marginRight: "-0.5rem" }}>
                  {/* Navigation Dropdown */}
                  <div 
                    style={{ position: "relative" }}
                    onMouseEnter={() => setShowNavDropdown(true)}
                    onMouseLeave={() => setShowNavDropdown(false)}
                  >
                    <button
                      className="btn btn-outline"
                      style={{ padding: "0.7rem 1.2rem", fontSize: "1.5rem" }}
                    >
                      ☰
                    </button>
                    {showNavDropdown && (
                      <div className="nav-dropdown">
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("dashboard");
                            setShowNavDropdown(false);
                          }}
                        >
                          📈 Dashboard
                        </button>
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("history");
                            setShowNavDropdown(false);
                          }}
                        >
                          📊 Istoric
                        </button>
                        <button
                          className="nav-dropdown-item"
                          onClick={() => {
                            onNavigate("goals");
                            setShowNavDropdown(false);
                          }}
                        >
                          🎯 Obiective
                        </button>
                      </div>
                    )}
                  </div>
                  
                  <div style={{
                    width: "1px",
                    height: "30px",
                    background: "rgba(255,255,255,0.3)",
                    margin: "0 0.5rem"
                  }}></div>
                  
                  {/* User Dropdown */}
                  <div 
                    style={{ position: "relative" }}
                    onMouseEnter={handleUserMouseEnter}
                    onMouseLeave={handleUserMouseLeave}
                  >
                    <button
                      className="btn btn-outline"
                      style={{ 
                        display: "flex",
                        alignItems: "center",
                        gap: "0.5rem"
                      }}
                    >
                      👤 {userEmail}
                      <span style={{ 
                        fontSize: "0.7rem",
                        transition: "transform 0.3s",
                        display: "inline-block",
                        transform: showUserDropdown ? "rotate(90deg)" : "rotate(0deg)"
                      }}>►</span>
                    </button>
                    {showUserDropdown && (
                      <div className="user-dropdown">
                        <button className="user-dropdown-item" onClick={() => alert('🚧 Profil - Coming soon!')}>
                          <span className="dropdown-icon">👤</span>
                          Profil
                        </button>
                        
                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("personal-data");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">📊</span>
                          Date personale
                        </button>
                        
                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("account-settings");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">🔑</span>
                          Setările contului
                        </button>

                        <button className="user-dropdown-item" onClick={() => {
                          onNavigate("app-settings");
                          setShowUserDropdown(false);
                        }}>
                          <span className="dropdown-icon">⚙️</span>
                          Setări aplicație
                        </button>
                        
                        <div className="user-dropdown-divider"></div>
                        <button className="user-dropdown-item logout-item" onClick={onLogout}>
                          <span className="dropdown-icon">🚪</span>
                          Logout
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              </>
            ) : (
              <div style={{ display: "flex", gap: "0.5rem", marginLeft: "auto" }}>
                <button
                  className="btn btn-outline"
                  onClick={() => onNavigate("login")}
                >
                  Login
                </button>
                <button
                  className="btn btn-secondary"
                  onClick={() => onNavigate("register")}
                >
                  Register
                </button>
              </div>
            )}
          </div>
        </div>
      </header>

      {/* Main Content Container */}
      <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "3rem 2rem" }}>
        {/* Hero Section */}
        <div style={{ textAlign: "center", marginBottom: "4rem" }}>
          <h1 style={{ 
            fontSize: "3.5rem", 
            fontWeight: "800", 
            color: "#ff6b35",
            marginBottom: "1rem",
            textShadow: "2px 2px 4px rgba(0,0,0,0.1)"
          }}>
            ✨ Bine ai venit la SmartChef! ✨
          </h1>
          <p style={{ 
            fontSize: "1.3rem", 
            color: "#666",
            fontWeight: "400",
            maxWidth: "800px",
            margin: "0 auto"
          }}>
            Analiză inteligentă a alimentelor cu AI și valori nutriționale
          </p>
        </div>

        {/* Feature Cards */}
        <div style={{ 
          display: "grid", 
          gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", 
          gap: "2rem",
          marginBottom: "4rem"
        }}>
          <div className="feature-card">
            <div className="feature-icon">🔍</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Recunoaștere AI
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              Detectează automat ingredientele din fotografii folosind inteligență artificială
            </p>
          </div>

          <div className="feature-card">
            <div className="feature-icon">📊</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Valori Nutriționale
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              Calculează automat calorii, proteine, carbohidrați și alte valori
            </p>
          </div>

          <div className="feature-card">
            <div className="feature-icon">🔒</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Securitate 2FA
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              Contul tău este protejat cu autentificare în doi pași
            </p>
          </div>
        </div>

        {/* Additional Features Section */}
        <div style={{ 
          display: "grid", 
          gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", 
          gap: "2rem",
          marginBottom: "4rem"
        }}>
          <div className="feature-card">
            <div className="feature-icon">📈</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Dashboard Statistici
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              Vizualizează evoluția consumului caloric și grafice interactive cu analiza alimentelor tale
            </p>
          </div>

          <div className="feature-card">
            <div className="feature-icon">🎯</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Obiective Personalizate
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              Setează-ți obiective nutriționale cu calculator BMR/TDEE și tracking progress zilnic
            </p>
          </div>

          <div className="feature-card">
            <div className="feature-icon">⚖️</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Tracking Greutate
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              Monitorizează evoluția greutății cu timeline interactiv și statistici detaliate
            </p>
          </div>

          <div className="feature-card">
            <div className="feature-icon">🔥</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Streak Counter
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              Menține activitatea zilnică și urmărește recordul tău de zile consecutive
            </p>
          </div>

          <div className="feature-card">
            <div className="feature-icon">🎨</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Personalizare Avansată
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              5 teme de culori, control mărime font, limbă, unități de măsură și pagină implicită
            </p>
          </div>

          <div className="feature-card">
            <div className="feature-icon">📜</div>
            <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
              Istoric Detaliat
            </h3>
            <p style={{ color: "#666", lineHeight: "1.6" }}>
              Păstrează toate analizele tale cu filtre avansate, export PDF și căutare rapidă
            </p>
          </div>
        </div>

        {/* CTA Section */}
        {!authToken ? (
          <div className="card" style={{ 
            maxWidth: "600px", 
            margin: "4rem auto 0", 
            textAlign: "center",
            padding: "3rem"
          }}>
            <h2 style={{ fontSize: "2rem", color: "#ff6b35", marginBottom: "1rem" }}>
              🚀 Începe Acum
            </h2>
            <p style={{ fontSize: "1.1rem", color: "#666", marginBottom: "2rem" }}>
              Creează un cont gratuit pentru a accesa toate funcționalitățile SmartChef
            </p>
            <div style={{ display: "flex", gap: "1rem", justifyContent: "center" }}>
              <button
                className="btn btn-primary"
                onClick={() => onNavigate("register")}
                style={{ padding: "1rem 2.5rem", fontSize: "1.1rem" }}
              >
                📝 Înregistrare Gratuită
              </button>
              <button
                className="btn btn-outline"
                onClick={() => onNavigate("login")}
                style={{ padding: "1rem 2.5rem", fontSize: "1.1rem" }}
              >
                🔐 Login
              </button>
            </div>
          </div>
        ) : (
          <div style={{ textAlign: "center", marginTop: "4rem" }}>
            <div style={{
              background: "linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%)",
              color: "white",
              padding: "3rem",
              borderRadius: "20px",
              boxShadow: "0 10px 30px rgba(255, 107, 53, 0.3)"
            }}>
              <h2 style={{ fontSize: "2.5rem", marginBottom: "1rem", fontWeight: "700" }}>
                🍽️ Gata să analizezi mâncarea ta?
              </h2>
              <p style={{ fontSize: "1.2rem", marginBottom: "2rem", opacity: 0.95 }}>
                Încarcă o imagine și descoperă instant valorile nutriționale
              </p>
              <button
                className="btn"
                onClick={() => onNavigate("analyze-food")}
                style={{ 
                  background: "white",
                  color: "#ff6b35",
                  padding: "1.2rem 3rem",
                  fontSize: "1.2rem",
                  fontWeight: "700",
                  border: "none",
                  boxShadow: "0 4px 15px rgba(0,0,0,0.2)"
                }}
              >
                📸 Analizează Acum
              </button>
            </div>
          </div>
        )}
      </div>

      {/* Floating Action Button */}
      <div className="fab-container">
        <button
          className="fab-menu-item fab-menu-item-1"
          onClick={toggleDarkMode}
          title={darkMode ? "Switch to Light Mode" : "Switch to Dark Mode"}
          style={{ display: "none" }}
        >
          {darkMode ? "☀️" : "🌙"}
        </button>
        <button
          className="fab-menu-item fab-menu-item-2"
          onClick={handleSettings}
          title="Settings"
          style={{ display: "none" }}
        >
          ⚙️
        </button>
        <button
          className="fab-menu-item fab-menu-item-3"
          onClick={handleHelp}
          title="Help & Support"
          style={{ display: "none" }}
        >
          ❓
        </button>
      </div>
    </div>
  );
}

export default Home;
